head.script:
// 화면 리사이징

scwin.contnId;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.init();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");

    // 2021-03-12 KBoY Deafult 에 2020-01-01 넣음
    //    edt_SDate.text = cGetMinusMonth(vCurDate.substring(0,4), vCurDate.substring(4,6), vCurDate.substring(6,8), 1);     // 한달전 날짜

    edt_EDate.setValue(vCurDate);
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'TITLE') {
            const options = {
                id: "ULDSTF30301",
                title: "보고및자료공유방 수정",
                type: "browserPopup",
                width: "770px",
                height: 575 + 40,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/bizspt/ULDSTF30301.gfm", options);
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30300.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.contnId = "input";
        const options = {
            id: "ULDSTF30301",
            title: "지식공유방 등록",
            type: "browserPopup",
            width: "770px",
            height: 575 + 40,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/bizspt/ULDSTF30301.gfm", options);
        scwin.contnId = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30300.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name dts_listShareRoom_OnLoadCompleted
 * @description dts_listShareRoom 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_listShareRoom_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_listShareRoom.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.dts_listShareRoom_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_listShareRoom_OnLoadError
 * @description dts_listShareRoom 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_listShareRoom_OnLoadError = function() {
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30300.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30300.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "지식공유방", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name rdo_creatloc_tp_onselchange
 * @description rdo_creatloc_tp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_creatloc_tp_onselchange = function() {
    try {
        if (rdo_creatloc_tp.getValue() !== '99') {
            dts_KnowlgTp.UseFilter = true;
            dts_KnowlgTp.Filter();
            cmb_knowlg_tp.trigger("onclick");
        } else {
            dts_KnowlgTp.UseFilter = true;
            dts_KnowlgTp.Filter();
            dts_KnowlgTp.sort('+VALUE', 0);
            // dts_KnowlgTp.sort(); // W-Craft 주석처리
            cmb_knowlg_tp.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.rdo_creatloc_tp_onselchange" });
    }
};

/**
 * @method
 * @name dts_KnowlgTp_OnFilter
 * @description Knowlg Tp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_KnowlgTp_OnFilter = function(row) {
    try {
        // alert(dts_KnowlgTp.NameValue(row, "value").substr(0,1) );
        //  생성처에 따른 지식구분을 가져온다.
        if (rdo_creatloc_tp.getValue() === '01') {
            if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === 'A' ||
                dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === '') {
                return true;
            } else {
                return false;
            }
        } else if (rdo_creatloc_tp.getValue() === '02') {
            if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === 'B' ||
                dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === '') {
                return true;
            } else {
                return false;
            }
        } else if (rdo_creatloc_tp.getValue() === '99') {
            return true;
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30300.dts_KnowlgTp_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 지식구분 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  지식구분 셋팅
    const sbmOptions = {
        id : "sbm_dts_KnowlgTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_KnowlgTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const KeyWord = $c.cp.valueOfIndex(keyword, "VALUE", keyword.getSelectedIndex());
    const Condition = condition1.getValue();
    // var UserId = condition2.value;
    const SDate = edt_SDate.getValue();
    const EDate = edt_EDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_listShareRoom",
        action : "/ShareRoom.do",
        ref : "",
        target : "dts_listShareRoom=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (scwin.contnId !== "input") {
        scwin.contnId = dts_listShareRoom.getCellData(Number(obj), "CONTN_ID");
    }
};

/**
 * @method
 * @name getContnId
 * @description get Contn Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.contnId;
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
